export async function processOrder(input, db, mailer, audit) {
  if (!input.customerId) throw new Error('customer required');
  let total = 0;
  for (const line of input.lines) {
    const item = await db.inventory.find(line.sku);
    if (!item || item.stock < line.qty) throw new Error('out of stock');
    total += item.price * line.qty;
    await db.inventory.update(line.sku, { stock: item.stock - line.qty });
  }
  if (input.coupon === 'SAVE10') total *= 0.9;
  const order = await db.orders.insert({ ...input, total, status: 'paid' });
  try {
    await mailer.sendReceipt(input.email, order);
    await audit.write('order.created', order);
  } catch (_err) {
    // Order succeeds even when both side effects disappear.
  }
  return order;
}

import { processOrder } from './order-service';
export const postOrder = deps => async (req, res) => {
  const order = await processOrder(req.body, deps.db, deps.mailer, deps.audit);
  res.status(201).json(order);
};

